const input = $input.first()?.json ?? {};
let texts = Array.isArray(input.texts) ? input.texts : [];
if (!texts.length && typeof input.text === 'string') texts = [input.text];
if (!texts.length && typeof input.query === 'string') texts = [input.query];
if (!texts.length && Array.isArray(input.document?.chunks)) texts = input.document.chunks.map((chunk) => chunk?.content);
texts = texts.map((value) => String(value ?? '').trim());
if (!texts.length || texts.some((value) => !value)) throw new Error('embedding texts must contain non-empty strings');
const dimensions = Number('__EMBEDDING_DIMENSIONS__');
if (!Number.isInteger(dimensions) || dimensions < 1) throw new Error('embedding dimensions must be a positive integer');
return [{ json: {
  request: {
    model: '__EMBEDDING_MODEL__',
    input: texts,
    dimensions,
    encoding_format: 'float',
  },
  expected_count: texts.length,
  dimensions,
} }];

const response = $input.first()?.json ?? {};
const request = $('Build Embedding Request').first().json;
const data = Array.isArray(response.data) ? response.data : [];
if (String(response.object ?? '') !== 'list') throw new Error('embedding response object must be list');
if (data.length !== request.expected_count) throw new Error(`embedding count mismatch: expected ${request.expected_count}, got ${data.length}`);
const ordered = [...data].sort((left, right) => Number(left?.index) - Number(right?.index));
const embeddings = ordered.map((item, index) => {
  if (Number(item?.index) !== index) throw new Error(`embedding index mismatch at ${index}`);
  const embedding = item?.embedding;
  if (!Array.isArray(embedding) || embedding.length !== request.dimensions) throw new Error(`embedding[${index}] must contain ${request.dimensions} values`);
  if (embedding.some((value) => !Number.isFinite(Number(value)))) throw new Error(`embedding[${index}] contains non-finite values`);
  return embedding;
});
return [{ json: {
  embeddings,
  model: String(response.model ?? request.request.model),
  dimensions: request.dimensions,
  count: embeddings.length,
  prompt_eval_count: Number(response.usage?.prompt_tokens ?? 0),
} }];
